const source = $input.first().json;
const tree = source.tree || [];
const files = tree
  .filter(i => i.type === 'blob')
  .filter(i => i.path === 'README.md' || (i.path.startsWith('docs/') && i.path.endsWith('.md')));

// HTTP Request processes each input item independently.  Emit one item per
// path rather than a single array, so every Markdown file is fetched once.
return files.map(file => ({
  json: { path: file.path, source_tree_sha: source.sha || null },
  pairedItem: { item: 0 }
}));

const responses = $input.all();
const sourceItems = $items('Filter Markdown');
if (responses.length !== sourceItems.length) {
  throw new Error(`Document fetch count mismatch: expected ${sourceItems.length}, received ${responses.length}`);
}

const contents = responses.map((item, index) => {
  const response = item.json;
  const content = typeof response.data === 'string'
    ? response.data
    : typeof response.body === 'string'
      ? response.body
      : JSON.stringify(response);
  return { path: sourceItems[index].json.path, content };
});

return [{
  json: {
    contents,
    source_tree_sha: sourceItems[0]?.json.source_tree_sha || null
  }
}];

const input = $input.first().json;
const contents = input.contents || [];
if (contents.length === 0) {
  throw new Error('No README.md or docs/*.md files were found to analyze');
}
const docs = contents.map(c => `--- ${c.path} ---
${c.content}`).join('

');
const system = 'You are a technical analyst. Analyze the provided repository documents and return a single JSON object with the following schema: { repository_summary: string, reuse_candidates: Array<{title:string,description:string,source_files:Array<string>,reusability_score:number,notes:string}>, cautions: Array<{category:string,description:string,source_files:Array<string>}>, metadata: {analyzed_at:string,total_files:number,file_paths:Array<string>} }. Respond only with the JSON object, no markdown fences.';
const body = JSON.stringify({
  model: $('Set Config').item.json.llmModel || 'gpt-4o-mini',
  messages: [{role:'system',content:system},{role:'user',content:docs}],
  response_format: {type:'json_object'},
  max_tokens: 8000
});
return [{ json: { body, fileCount: contents.length, paths: contents.map(c => c.path), source_tree_sha: input.source_tree_sha } }];

const raw = $input.first().json.choices?.[0]?.message?.content;
if (!raw) {
  throw new Error('LLM response did not contain message content');
}
try {
  return [{ json: JSON.parse(raw) }];
} catch (error) {
  throw new Error(`LLM response was not valid JSON: ${error.message}`);
}

const analysis = $input.first().json;
const now = new Date().toISOString();
const config = $('Set Config').item.json;
const prompt = $('Build Prompt').item.json;
const paths = prompt.paths || [];
const chunks = paths.map(p => ({
  chunk_id: p.replace(/[^a-zA-Z0-9]/g, '-'),
  source_path: p,
  content_digest: 'auto',
  embedding_ready: true
}));
const out = {
  schema_version: 'luvira.repo-analysis.v1',
  repository: config.repoOwner + '/' + config.repoName,
  source_ref: config.branch,
  source_tree_sha: prompt.source_tree_sha || null,
  generated_at: now,
  summary: { repository_summary: analysis.repository_summary || '' },
  reuse_candidates: analysis.reuse_candidates || [],
  cautions: analysis.cautions || [],
  chunks,
  raw_analysis: analysis
};
return [{ json: out }];
